using System.Security.Cryptography;
using System.Text;

namespace SqlDataCollector.Infrastructure;

/// <summary>
/// Encrypts secrets stored in the metadata database (e.g. the GCS service account key) with AES-256-GCM.
/// The key is Secrets:Key in each process's appsettings (base64, 32 bytes; generated by the installer); every process that
/// reads the secret (Web, Workers) needs the same key. Database backups and DBAs only see ciphertext.
/// </summary>
public sealed class SecretProtector(IConfiguration configuration)
{
    public const string ConfigKey = "Secrets:Key";
    private const string Prefix = "v1:";

    public bool IsConfigured => TryGetKey(out _);

    public static string NewKey() => Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));

    public string Protect(string plaintext)
    {
        var key = GetKey();
        var nonce = RandomNumberGenerator.GetBytes(AesGcm.NonceByteSizes.MaxSize);
        var plain = Encoding.UTF8.GetBytes(plaintext);
        var cipher = new byte[plain.Length];
        var tag = new byte[AesGcm.TagByteSizes.MaxSize];
        using (var aes = new AesGcm(key, tag.Length)) aes.Encrypt(nonce, plain, cipher, tag);
        return Prefix + Convert.ToBase64String([.. nonce, .. tag, .. cipher]);
    }

    public string Unprotect(string protectedValue)
    {
        if (!protectedValue.StartsWith(Prefix, StringComparison.Ordinal)) throw new InvalidOperationException("Unknown secret format.");
        var key = GetKey();
        var data = Convert.FromBase64String(protectedValue[Prefix.Length..]);
        int n = AesGcm.NonceByteSizes.MaxSize, t = AesGcm.TagByteSizes.MaxSize;
        if (data.Length < n + t) throw new InvalidOperationException("The stored secret is truncated.");
        var plain = new byte[data.Length - n - t];
        try
        {
            using var aes = new AesGcm(key, t);
            aes.Decrypt(data.AsSpan(0, n), data.AsSpan(n + t), data.AsSpan(n, t), plain);
        }
        catch (AuthenticationTagMismatchException)
        {
            throw new InvalidOperationException($"The stored secret cannot be decrypted: {ConfigKey} of this process differs from the one used to store it.");
        }
        return Encoding.UTF8.GetString(plain);
    }

    private byte[] GetKey() => TryGetKey(out var k) ? k
        : throw new InvalidOperationException($"{ConfigKey} is not configured (base64, 32 bytes). The installer writes it; all processes need the same value.");

    private bool TryGetKey(out byte[] key)
    {
        key = [];
        var s = configuration[ConfigKey];
        if (string.IsNullOrWhiteSpace(s)) return false;
        try { key = Convert.FromBase64String(s.Trim()); } catch (FormatException) { return false; }
        return key.Length == 32;
    }
}
